    var S2 = function (txt, x) { x = x || {}; d.para(txt, Object.assign({ align: "left", left: 9.5, after: 0, line: 240 }, x, { size: (x.size || 13) * k })); };
    S2("Выполнил:", { before: 70 });
    S2("Курсант" + (t.group ? " " + t.group + " группы" : ""));
    S2(initials(t.student) || "");
    S2("Проверил:", { before: 18 });
    S2("Преподаватель");
