        if (!p.length) return; var t0 = p[0].t, t1 = p[p.length - 1].t, vm = Math.max.apply(null, p.map(function (q) { return Math.abs(q.s); }).concat([1])), x0 = 100, x1 = W - 40, y0 = 60, y1 = H - 70;
        function X(t) { return x0 + (x1 - x0) * (t - t0) / Math.max(1, t1 - t0); } function Y(v) { return (y0 + y1) / 2 - (y1 - y0) / 2 * v / (vm * 1.15); }
        c.strokeStyle = "#ddd"; c.lineWidth = 1; c.font = "20px " + FONT; c.fillStyle = "#444"; c.textAlign = "center";
