  /* ---------------- отчёт ---------------- */
  function vd(v) { return { variant: String(v), crew: "4" }; }
  function crewOf(d) { var k = parseInt(d.crew, 10); return CREWQ[k] ? k : 4; }
  function schedHead(v) { return ["№", "Должность", "Место сбора", "Обязанности"]; }
  function schedRows(v) { var n = 0; return v.rows.map(function (r) { return r.span !== undefined ? r : [String(++n)].concat(r); }); }
  function solve(d) {
    var v = V[d.variant] || V[1], k = crewOf(d), qs = CREWQ[k], st = [];
    st.push({ no: 1, title: "Нормативно-правовая база", lines: [], tables: [{ title: "Международные конвенции и кодексы", headers: ["Документ", "Англ. название"], rows: CONV.map(function (x) { return [x.t + " — " + x.ru, x.en]; }) },
      { title: "Национальные требования РФ", headers: ["Документ", "Что регулирует"], rows: NAT_DOCS }], answer: "СОЛАС, ПДНВ, МАРПОЛ, МКУБ, МППСС, MLC + КТМ РФ и уставы" });
    st.push({ no: 2, title: "Организация судового экипажа", lines: [], tables: [webTb({ tb: { h: ["Должность", "Обязанности"], r: CMD } }), { title: "Судовая команда", headers: ["Должность", "Обязанности"], rows: RANK }, { title: "Судовые расписания", headers: ["Расписание", "Назначение"], rows: SCHED }] });
    st.push({ no: 3, title: "Судовое расписание по " + v.alarm, given: v.data, lines: [], paras: ["Экипаж " + v.n + " чел.: " + v.crew + "."], tables: [{ title: "Сигналы", headers: ["Сигнал", "Значение"], rows: v.sig }, webTb({ tb: { h: schedHead(v), r: schedRows(v) } })],
      after: ["Заместители: " + v.subst].concat(v.notes), figs: ["scheme"], answer: "т/х «Надежда», " + v.ship + ", " + v.n + " чел., " + v.alarmShort });
    qs.forEach(function (n) {
      var q = Q[n], paras = [], tables = [];
      q.a.forEach(function (x) { if (typeof x === "string") paras.push(plain(x.slice(0, 2) === "- " ? "– " + x.slice(2) : x)); else tables.push(webTb(x)); });
      st.push({ no: 3 + st.length - 2, noLabel: "Вопрос " + n + ". ", title: q.q, lines: [], paras: paras, tables: tables });
    });
    return { steps: st, v: v, k: k, qs: qs };
  }
