    var S = [];
    st.groups.forEach(function (g) { g.rows.forEach(function (r) { S.push({ grp: g.g, rho: g.rho, name: r[0], m: r[1], X: r[2], Y: r[3], Z: r[4], dmh: r[5] || 0 }); }); });
