    var rho = num(o.rho, 1.025) || 1.025;
    var D = r1.D, Vd = D / rho, H = sh.hyd, warn = r1.warn.slice();
    if (!inRange(H, Vd, 1)) warn.push("Объёмное водоизмещение " + f(Vd, 1) + " м³ вне таблицы гидростатики — значения экстраполированы.");
    var br = bracket(H, Vd, 1);
    var hy = { d: lin(H, Vd, 1, 0), Xc: lin(H, Vd, 1, 3), Zc: lin(H, Vd, 1, 4), q: lin(H, Vd, 1, 5), Xf: lin(H, Vd, 1, 6), Zm: lin(H, Vd, 1, 7), ZM: lin(H, Vd, 1, 8), lo: br[0], hi: br[1] };
    /* свободные поверхности */
