  /* ---------- рисунки ---------- */
  function cv(c, w, h) { c.width = w; c.height = h; var g = c.getContext("2d"); g.fillStyle = "#fff"; g.fillRect(0, 0, w, h); g.lineCap = "round"; g.lineJoin = "round"; return g; }
  function txt(g, s, x, y, o) { o = o || {}; g.font = (o.w || "400") + " " + (o.s || 18) + "px Arial, sans-serif"; g.fillStyle = o.c || "#111"; g.textAlign = o.a || "center"; g.textBaseline = o.b || "middle"; g.fillText(s, x, y); }
