    for (var x = Math.ceil(X[0] / X[2]) * X[2]; x <= X[1] + 1e-9; x += X[2]) { line(g, [[px(x), y0], [px(x), y0 + h]], { c: "#d6dde3", w: 1 }); txt(g, f(x, X[3] || 0), px(x), py(Math.max(Y[0], 0)) + 16, { s: 15, c: "#333" }); }
    for (var y = Math.ceil(Y[0] / Y[2]) * Y[2]; y <= Y[1] + 1e-9; y += Y[2]) { line(g, [[x0, py(y)], [x0 + w, py(y)]], { c: "#d6dde3", w: 1 }); txt(g, f(y, Y[3] === undefined ? 1 : Y[3]), px(Math.max(X[0], 0)) - 8, py(y), { s: 15, c: "#333", a: "right" }); }
    arrow(g, px(X[0]), py(0), x0 + w + 18, py(0), { w: 2 }); arrow(g, px(Math.max(X[0], 0)), y0 + h, px(Math.max(X[0], 0)), y0 - 18, { w: 2 });
    txt(g, lab[0], x0 + w + 10, py(0) + 34, { s: 17, a: "right", w: "700" }); txt(g, lab[1], px(Math.max(X[0], 0)) + 10, y0 - 22, { s: 17, a: "left", w: "700" });
